{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "The overarching aim of the review is to identify and appraise any newly published evidence from around the world that assesses the impact of the COVID-19 pandemic on suicide deaths, suicidal behaviours, self-harm and suicidal thoughts, or that assesses the effectiveness of strategies to reduce the risk of suicide deaths, suicidal behaviours, self-harm and suicidal thoughts, resulting from the COVID-19 pandemic.",
      "reason": "The manuscript provides an explicit, overarching aim and clearly states the review questions/objectives (including both impact and effectiveness of strategies), fulfilling the requirement to state objectives/questions."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "Although the review includes assessment of effectiveness of strategies, the retrieved evidence does not present planned intervention comparisons framed using PICO or an appropriate variant; no PICO-style planned comparisons are explicitly reported in the provided text."
    }
  ],
  "confidence": 80
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_8",
      "quote": "Study participants may be adults or children of any ethnicities living in any country. Outcomes of interest are: \u0007 Deaths by suicide \u0007 Self-harm (intentional self-injury or self-poisoning regardless of motivation and intent) or attempted suicide (including hospital attendance and/or admission for these reasons) \u0007 Suicidal thoughts/ideation",
      "reason": "The manuscript specifies participant characteristics, settings (any country), and detailed outcomes of interest and research questions/study types (see text_8 and callout_0). However, it does not explicitly state follow-up requirements or other detailed study eligibility features (e.g. minimum follow-up duration), so not all study-characteristic eligibility elements are fully specified."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "No restrictions were placed on the types of study design eligible for inclusion, except for the exclusion of single-person case reports. Pre-prints were re-assessed at the time of publication and most current version included. There was no restriction on language of publication.",
      "reason": "The manuscript explicitly reports eligibility criteria for report characteristics (study design restrictions, handling of pre-prints, and no language restriction), and gives the date range for the current iteration (Jan 1 to June 7, 2020) in the same section."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit statement distinguishes exclusion because outcomes were not measured from exclusion because outcome results were not reported in the provided evidence."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "We synthesised studies according to themes based on research questions and study design, using tables and narrative. Results were synthesised separately for studies in the general population, in health and social care staff and other at-risk occupations, and in vulnerable populations (e.g. people of older age or those with underlying conditions that predispose them to becoming severely ill or dying after contracting COVID-19).",
      "reason": "The manuscript specifies the groups used in synthesis (by theme/study design and specific population groups) and links these to the research questions/comparisons."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PARTIAL",
      "chunk_id": "text_20",
      "quote": "We did not include Google Trends studies (Jacobson et al., 2020; Knipe et al., 2020; Rana, 2020; Sinyor et al., 2020) since search data constitute a proxy measure but findings are largely mixed. We also excluded grey literature (Fancourt & Steptoe, 2020).",
      "reason": "Rationales are provided for some notable restrictions (e.g. exclusion of Google Trends studies because search data are a proxy measure), but not for all restrictions (for example, exclusion of single-person case reports is stated elsewhere without an explicit rationale in the provided evidence), so the rationale coverage is incomplete."
    }
  ],
  "confidence": 85
}

